 using System.ComponentModel;
 using Microsoft.Extensions.AI;
 using Microsoft.Agents.AI;

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 IChatClient innerClient = new OpenAI.OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 var researchTools = new ResearchTools();

 IChatClient chatClient = new ChatClientBuilder(innerClient)
     .UseFunctionInvocation()
     .Build();

 var agent = new ChatClientAgent(
     chatClient,
     name: "ResearchAgent",
     instructions: "You are a research agent. Use the web_search tool to find information about the "
         + "requested topic. Use the take_note tool to record important findings as you go. "
         + "Perform multiple searches to gather comprehensive information, take notes on key "
         + "findings, then provide a final summary of your research.",
     tools: [
         AIFunctionFactory.Create(researchTools.WebSearch),
         AIFunctionFactory.Create(researchTools.TakeNote),
         AIFunctionFactory.Create(researchTools.GetNotes),
     ]);

 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
 });

 Console.WriteLine("Research Agent Starting...");
 Console.WriteLine($"Model: {modelId}");
 Console.WriteLine(new string('-', 60));

 var userMessage = "Research the latest advances in quantum computing in 2026. "
     + "Search for recent breakthroughs, key players, and practical applications.";

 await foreach (var update in agent.RunStreamingAsync(userMessage, options: runOptions))
 {
     if (!string.IsNullOrEmpty(update.Text))
     {
         Console.Write(update.Text);
     }
 }

 Console.WriteLine();
 Console.WriteLine(new string('-', 60));
 Console.WriteLine($"Notes collected: {researchTools.NoteCount}");

 // --- Tool definitions ---

 public sealed class ResearchTools
 {
     private readonly List<string> _notes = [];

     public int NoteCount => _notes.Count;

     [Description("Search the web for information on a given query. Returns search result snippets.")]
     public string WebSearch([Description("The search query")] string query)
     {
         // In production, integrate a real search API (Bing Search, Google Custom Search, etc.)
         Console.WriteLine($"\n  [Tool] web_search(\"{query}\")");

         return $"""
             Search results for: "{query}"

             1. "Quantum Computing Breakthroughs 2026" - TechReview
                IBM announced a 4,000+ qubit processor in early 2026, marking a major milestone
                in scalable quantum hardware. Error correction rates improved by 40%.

             2. "Google Willow Successor Achieves Quantum Advantage" - Nature
                Google's next-generation chip demonstrated practical quantum advantage on
                optimization problems relevant to drug discovery and materials science.

             3. "Microsoft Topological Qubits Reach Stability Milestone" - ArXiv
                Microsoft's topological qubit approach achieved record coherence times,
                making fault-tolerant quantum computing more feasible.

             4. "Quantum Computing Market Report 2026" - Gartner
                The quantum computing market is projected to reach $8.5B by 2028.
                Key players: IBM, Google, Microsoft, IonQ, Rigetti, and PsiQuantum.

             5. "Practical Quantum Applications in Finance and Pharma" - MIT Tech Review
                JPMorgan and Roche reported using quantum algorithms for portfolio optimization
                and molecular simulation respectively, achieving measurable speedups.
             """;
     }

     [Description("Record a research note with a title and content for later summarization.")]
     public string TakeNote(
         [Description("Short title for the note")] string title,
         [Description("Content of the note")] string content)
     {
         _notes.Add($"## {title}\n{content}");
         Console.WriteLine($"\n  [Tool] take_note(\"{title}\")");
         return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
     }

     [Description("Retrieve all notes taken so far during the research session.")]
     public string GetNotes()
     {
         Console.WriteLine("\n  [Tool] get_notes()");
         return _notes.Count == 0
             ? "No notes taken yet."
             : string.Join("\n\n", _notes);
     }
 }
